H.background();
// Linear thermal expansion:  delta L = alpha * L0 * delta T
// A heated rod grows; we read alpha, original length L0, and temperature change.
const w = H.W, h = H.H;
const alpha = P.alpha * 1e-6;          // slider in units of 1e-6 per degC
const L0 = P.L0;                        // original length in meters
const dTmax = P.dT;                     // max temperature change in degC
// Animate temperature change from 0 up to dTmax and back (looping heating/cooling).
const dT = dTmax * 0.5 * (1 - Math.cos(t * 0.8));
const dL = alpha * L0 * dT;             // change in length (m)
const L = L0 + dL;                      // current length (m)
const T = 20 + dT;                      // current temperature (degC), start at 20
H.text("Thermal expansion:  ΔL = α·L0·ΔT", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("α = " + P.alpha.toFixed(1) + "e-6 /°C    L0 = " + L0.toFixed(2) + " m    ΔT = " + dT.toFixed(1) + " °C", 24, 52, { color: H.colors.sub, size: 13 });
// Draw the rod as a bar. Exaggerate the length change visually so it is visible.
const baseX = 70;
const baseY = h * 0.5;
const pxPerM = (w - 160) / Math.max(0.5, L0);   // L0 maps to most of the width
// visual exaggeration factor so a tiny ΔL is seeable
const exaggerate = 1 + (dL / Math.max(1e-9, L0)) * 400;
const pxLen = pxPerM * L0 * exaggerate * 0.85;
const barH = 46;
// color from cool (blue) to hot (red) by temperature
const heat = H.clamp(dT / Math.max(1e-6, dTmax), 0, 1);
const rodColor = H.hsl(220 - 200 * heat, 80, 55);
// reference outline at original length
H.rect(baseX, baseY - barH / 2, pxPerM * L0 * 0.85, barH, { stroke: H.colors.grid, width: 1.5, radius: 4 });
// hot rod
H.rect(baseX, baseY - barH / 2, pxLen, barH, { fill: rodColor, radius: 4 });
// expansion arrow showing growth direction at the tip
H.arrow(baseX + pxPerM * L0 * 0.85, baseY, baseX + pxLen + 6, baseY, { color: H.colors.warn, width: 3, head: 10 });
// fixed wall on the left
H.rect(baseX - 14, baseY - barH, 14, barH * 2, { fill: H.colors.panel, stroke: H.colors.axis, width: 1.5 });
// labels
H.text("L0 = " + L0.toFixed(2) + " m", baseX, baseY + barH / 2 + 22, { color: H.colors.sub, size: 12 });
H.text("L = " + L.toFixed(5) + " m", baseX, baseY - barH / 2 - 12, { color: H.colors.accent, size: 13, weight: 600 });
// thermometer readout
H.text("T = " + T.toFixed(1) + " °C", w - 150, 52, { color: rodColor, size: 14, weight: 700 });
H.text("ΔL = " + (dL * 1000).toFixed(3) + " mm", w - 150, 74, { color: H.colors.good, size: 13 });
H.text("(visual stretch exaggerated)", baseX, baseY + barH / 2 + 40, { color: H.colors.sub, size: 11 });
